INSERT INTO archimate_dashboard_revisions (dashboard_id, revision, definition, created_by) VALUES
  ('demonstration-datasources', 1, $def_demonstration_datasources_1${"id":"demonstration-datasources","title":"Démonstration des datasources","description":"Présente côte à côte une métrique Neo4j et une métrique PostgreSQL de démonstration.","category":"Démonstration","schemaVersion":2,"parameters":[],"panels":[{"id":"elements-neo4j","panel":{"title":"Éléments","description":"Nombre total d’éléments ArchiMate affiché par le plugin d’exemple.","resultType":"metrics","parameters":[],"visualization":{"type":"example/progress","max":1000},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (element:Element) RETURN count(element) AS count"}},"layout":{"x":0,"y":0,"width":6,"height":3},"parameterBindings":{}},{"id":"fournisseurs-postgres","panel":{"title":"Fournisseurs actifs (démonstration PostgreSQL)","description":"Métrique issue du jeu de données PostgreSQL local de démonstration.","resultType":"metrics","query":{"datasourceId":"postgres","language":"sql","text":"SELECT count(*)::integer AS count FROM fournisseurs WHERE actif = $actif"},"parameters":[{"name":"actif","label":"Fournisseurs actifs","type":"boolean","required":false,"defaultValue":true}],"visualization":{"type":"core/metric"}},"layout":{"x":6,"y":0,"width":6,"height":3},"parameterBindings":{}}],"createdAt":"2026-08-07T20:00:00.000Z","updatedAt":"2026-08-07T20:00:00.000Z","createdBy":"codex","updatedBy":"codex"}$def_demonstration_datasources_1$::jsonb, 'codex'),
  ('motivation', 1, $def_motivation_1${"id":"motivation","title":"Chaîne de motivation par driver","description":"Affiche les Drivers, Assessments, Goals et Outcomes reliés au driver sélectionné.","category":"Motivation","schemaVersion":2,"parameters":[{"name":"driverId","label":"Driver","type":"string","required":true,"selector":{"source":"model-elements","elementTypes":["Driver"]}}],"panels":[{"id":"chaine-motivation","panel":{"title":"Chaîne de motivation par driver","description":"Affiche les Drivers, Assessments, Goals et Outcomes reliés au driver sélectionné.","resultType":"graph","parameters":[{"name":"driverId","label":"Driver","type":"string","required":true,"selector":{"source":"model-elements","elementTypes":["Driver"]}}],"visualization":{"colorByProperty":"type","type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (driver:Element {id: $driverId, type: 'Driver'})\nOPTIONAL MATCH path = (driver)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..5]-(target:Element)\nWHERE target.type IN ['Assessment', 'Goal', 'Outcome']\n  AND all(node IN nodes(path) WHERE node.type IN ['Driver', 'Assessment', 'Goal', 'Outcome'])\nWITH driver, reduce(allNodes = [driver], pathNodes IN collect(nodes(path)) | allNodes + coalesce(pathNodes, [])) AS pathNodes\nUNWIND pathNodes AS node\nWITH driver, node WHERE node IS NOT NULL\nRETURN collect(DISTINCT node.id) AS nodeIds, driver.id AS emphasizedId"}},"layout":{"x":0,"y":0,"width":12,"height":8},"parameterBindings":{"driverId":{"source":"dashboard","parameter":"driverId"}}}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_motivation_1$::jsonb, 'christophe.lacombe'),
  ('principles', 1, $def_principles_1${"id":"principles","title":"Chaîne de conformité par principe","description":"Affiche le principe sélectionné et les exigences et contraintes qui lui sont reliées.","category":"Motivation","schemaVersion":2,"parameters":[{"name":"principleId","label":"Principe","type":"string","required":true,"selector":{"source":"model-elements","elementTypes":["Principle"]}}],"panels":[{"id":"chaine-conformite","panel":{"title":"Chaîne de conformité par principe","description":"Affiche le principe sélectionné et les exigences et contraintes qui lui sont reliées.","resultType":"graph","parameters":[{"name":"principleId","label":"Principe","type":"string","required":true,"selector":{"source":"model-elements","elementTypes":["Principle"]}}],"visualization":{"colorByProperty":"type","type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (principle:Element {id: $principleId, type: 'Principle'})\nOPTIONAL MATCH constraintPath = (principle)--(requirement:Element {type: 'Requirement'})--(constraint:Element {type: 'Constraint'})\nWITH principle, [pathNodes IN collect(nodes(constraintPath)) WHERE pathNodes IS NOT NULL] AS constraintPaths\nOPTIONAL MATCH (principle)--(directRequirement:Element {type: 'Requirement'})\nWITH principle, constraintPaths, collect(DISTINCT directRequirement) AS directRequirements\nWITH principle, CASE\n  WHEN size(constraintPaths) > 0\n  THEN reduce(allNodes = [], pathNodes IN constraintPaths | allNodes + pathNodes)\n  ELSE [principle] + directRequirements\nEND AS selectedNodes\nUNWIND selectedNodes AS node\nRETURN collect(DISTINCT node.id) AS nodeIds, principle.id AS emphasizedId"}},"layout":{"x":0,"y":0,"width":12,"height":8},"parameterBindings":{"principleId":{"source":"dashboard","parameter":"principleId"}}}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_principles_1$::jsonb, 'christophe.lacombe'),
  ('rapports-application', 1, $def_rapports_application_1${"id":"rapports-application","title":"Rapports application","description":"Acteurs métier, fonctions, technologies et exigences d’une application.","category":"Applications","schemaVersion":2,"parameters":[{"name":"appId","label":"Application","type":"string","required":true,"selector":{"source":"model-elements","elementTypes":["ApplicationComponent"]}}],"panels":[{"id":"acteurs-metier","panel":{"title":"Acteurs métier (voisinage applicatif)","description":"Acteurs et rôles métier atteints depuis un composant applicatif donné, jusqu'à 2 sauts.","resultType":"graph","parameters":[{"name":"appId","label":"Identifiant de l'application","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (:Element {id: $appId, type: 'ApplicationComponent'})-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..2]-(target:Element)\nWHERE target.type IN ['BusinessActor', 'BusinessRole']\nWITH DISTINCT target LIMIT 500\nRETURN collect(target.id) AS nodeIds"}},"layout":{"x":0,"y":0,"width":6,"height":7},"parameterBindings":{"appId":{"source":"dashboard","parameter":"appId"}}},{"id":"fonctions-metier","panel":{"title":"Fonctions métier","description":"Composants applicatifs directement liés à l’application sélectionnée.","resultType":"graph","parameters":[{"name":"appId","label":"Application","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (root:Element {id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (root)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..1]-(other:Element {type: 'ApplicationComponent'})\nWITH root, collect(DISTINCT other.id) AS others\nRETURN others + [root.id] AS nodeIds, root.id AS emphasizedId"}},"layout":{"x":6,"y":0,"width":6,"height":7},"parameterBindings":{"appId":{"source":"dashboard","parameter":"appId"}}},{"id":"composants-technologiques","panel":{"title":"Composants technologiques","description":"Éléments technologiques documentés comme appartenant à l’application sélectionnée.","resultType":"graph","parameters":[{"name":"appId","label":"Application","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (app:Element {id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (tech:Element {layer: 'Technology'})-[:HAS_PROPERTY]->(:Property {name: 'Application', value: app.name})\nWITH [item IN collect(DISTINCT tech) WHERE item IS NOT NULL | item] AS techs\nUNWIND CASE WHEN size(techs) = 0 THEN [null] ELSE techs END AS tech\nWITH techs, collect(CASE\n  WHEN tech IS NULL THEN null\n  WHEN tech.type = 'CommunicationNetwork' AND NOT EXISTS { MATCH (tech)-[:COMPOSITION|AGGREGATION]->(:Element {type: 'CommunicationNetwork'}) } THEN {id: tech.id, rankGroup: 'subnet'}\n  WHEN tech.type = 'TechnologyInterface' THEN {id: tech.id, rankGroup: 'private-endpoint'}\n  ELSE null END) AS rawRankGroups\nRETURN [tech IN techs | tech.id] AS nodeIds, [item IN rawRankGroups WHERE item IS NOT NULL | item] AS rankGroups"}},"layout":{"x":0,"y":7,"width":6,"height":7},"parameterBindings":{"appId":{"source":"dashboard","parameter":"appId"}}},{"id":"traceabilite-exigences","panel":{"title":"Traçabilité des exigences","description":"Exigences réalisées par les composants technologiques de l’application sélectionnée.","resultType":"graph","parameters":[{"name":"appId","label":"Application","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (app:Element {id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (tech:Element {layer: 'Technology'})-[:HAS_PROPERTY]->(:Property {name: 'Application', value: app.name})\n               WHERE (tech)-[:REALIZATION]->(:Element {type: 'Requirement', layer: 'Motivation'})\nOPTIONAL MATCH (tech)-[:REALIZATION]->(requirement:Element {type: 'Requirement', layer: 'Motivation'})\nWITH collect(DISTINCT tech.id) AS techIds, collect(DISTINCT requirement.id) AS requirementIds\nRETURN [id IN techIds + requirementIds WHERE id IS NOT NULL | id] AS nodeIds"}},"layout":{"x":6,"y":7,"width":6,"height":7},"parameterBindings":{"appId":{"source":"dashboard","parameter":"appId"}}}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_rapports_application_1$::jsonb, 'christophe.lacombe'),
  ('rapports-application', 2, $def_rapports_application_2${"id":"rapports-application","title":"Rapports application","description":"Acteurs métier, fonctions, technologies et exigences d’une application.","category":"Applications","schemaVersion":2,"parameters":[{"name":"appId","label":"Application","type":"string","required":true,"selector":{"source":"model-elements","elementTypes":["ApplicationComponent"]}}],"panels":[{"id":"acteurs-metier","panel":{"title":"Acteurs métier (voisinage applicatif)","description":"Acteurs et rôles métier atteints depuis un composant applicatif donné, jusqu'à 2 sauts.","resultType":"graph","parameters":[{"name":"appId","label":"Identifiant de l'application","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (:Element {id: $appId, type: 'ApplicationComponent'})-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..2]-(target:Element)\nWHERE target.type IN ['BusinessActor', 'BusinessRole']\nWITH DISTINCT target LIMIT 500\nRETURN collect(target.id) AS nodeIds"}},"layout":{"x":0,"y":0,"width":6,"height":7},"parameterBindings":{"appId":{"source":"dashboard","parameter":"appId"}}},{"id":"fonctions-metier","panel":{"title":"Fonctions métier","description":"Composants applicatifs directement liés à l’application sélectionnée.","resultType":"graph","parameters":[{"name":"appId","label":"Application","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (root:Element {id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (root)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION*1..1]-(other:Element {type: 'ApplicationComponent'})\nWITH root, collect(DISTINCT other.id) AS others\nRETURN others + [root.id] AS nodeIds, root.id AS emphasizedId"}},"layout":{"x":6,"y":0,"width":6,"height":7},"parameterBindings":{"appId":{"source":"dashboard","parameter":"appId"}}},{"id":"composants-technologiques","panel":{"title":"Composants technologiques","description":"Éléments technologiques documentés comme appartenant à l’application sélectionnée.","resultType":"graph","parameters":[{"name":"appId","label":"Application","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (app:Element {id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (tech:Element {layer: 'Technology'})-[:HAS_PROPERTY]->(:Property {name: 'Application', value: app.name})\nWITH [item IN collect(DISTINCT tech) WHERE item IS NOT NULL | item] AS techs\nUNWIND CASE WHEN size(techs) = 0 THEN [null] ELSE techs END AS tech\nWITH techs, collect(CASE\n  WHEN tech IS NULL THEN null\n  WHEN tech.type = 'CommunicationNetwork' AND NOT EXISTS { MATCH (tech)-[:COMPOSITION|AGGREGATION]->(:Element {type: 'CommunicationNetwork'}) } THEN {id: tech.id, rankGroup: 'subnet'}\n  WHEN tech.type = 'TechnologyInterface' THEN {id: tech.id, rankGroup: 'private-endpoint'}\n  ELSE null END) AS rawRankGroups\nRETURN [tech IN techs | tech.id] AS nodeIds, [item IN rawRankGroups WHERE item IS NOT NULL | item] AS rankGroups"}},"layout":{"x":0,"y":7,"width":6,"height":7},"parameterBindings":{"appId":{"source":"dashboard","parameter":"appId"}}},{"id":"traceabilite-exigences","panel":{"title":"Traçabilité des exigences","description":"Exigences réalisées par les composants technologiques de l’application sélectionnée.","resultType":"graph","parameters":[{"name":"appId","label":"Application","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (app:Element {id: $appId, type: 'ApplicationComponent'})\nOPTIONAL MATCH (tech:Element {layer: 'Technology'})-[:HAS_PROPERTY]->(:Property {name: 'Application', value: app.name})\n               WHERE (tech)-[:REALIZATION]->(:Element {type: 'Requirement', layer: 'Motivation'})\nOPTIONAL MATCH (tech)-[:REALIZATION]->(requirement:Element {type: 'Requirement', layer: 'Motivation'})\nWITH collect(DISTINCT tech.id) AS techIds, collect(DISTINCT requirement.id) AS requirementIds\nRETURN [id IN techIds + requirementIds WHERE id IS NOT NULL | id] AS nodeIds"}},"layout":{"x":6,"y":7,"width":6,"height":7},"parameterBindings":{"appId":{"source":"dashboard","parameter":"appId"}}}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_rapports_application_2$::jsonb, 'christophe.lacombe'),
  ('rapports-architecture', 1, $def_rapports_architecture_1${"id":"rapports-architecture","title":"Rapports d’Architecture","description":"Vue d’ensemble du modèle ArchiMate courant.","category":"Architecture","schemaVersion":2,"parameters":[],"panels":[{"id":"elements","panel":{"title":"Éléments","description":"Nombre total d’éléments ArchiMate.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (element:Element) RETURN count(element) AS count"}},"layout":{"x":0,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"relations","panel":{"title":"Relations","description":"Nombre total de relations ArchiMate.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (:Element)-[relationship]->(:Element) RETURN count(relationship) AS count"}},"layout":{"x":3,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"vues","panel":{"title":"Vues","description":"Nombre total de vues ArchiMate.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (view:View) RETURN count(view) AS count"}},"layout":{"x":6,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"couches","panel":{"title":"Couches ArchiMate","description":"Nombre de couches présentes dans le modèle.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (element:Element) RETURN count(DISTINCT element.layer) AS count"}},"layout":{"x":9,"y":0,"width":3,"height":3},"parameterBindings":{}}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_rapports_architecture_1$::jsonb, 'christophe.lacombe'),
  ('rapports-architecture', 2, $def_rapports_architecture_2${"id":"rapports-architecture","title":"Rapports d’Architecture","description":"Vue d’ensemble du modèle ArchiMate courant.","category":"Architecture","schemaVersion":2,"parameters":[],"panels":[{"id":"elements","panel":{"title":"Éléments","description":"Nombre total d’éléments ArchiMate affiché par le plugin d’exemple.","resultType":"metrics","parameters":[],"visualization":{"type":"example/progress","max":1000},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (element:Element) RETURN count(element) AS count"}},"layout":{"x":0,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"relations","panel":{"title":"Relations","description":"Nombre total de relations ArchiMate.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (:Element)-[relationship]->(:Element) RETURN count(relationship) AS count"}},"layout":{"x":3,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"vues","panel":{"title":"Vues","description":"Nombre total de vues ArchiMate.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (view:View) RETURN count(view) AS count"}},"layout":{"x":6,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"couches","panel":{"title":"Couches ArchiMate","description":"Nombre de couches présentes dans le modèle.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (element:Element) RETURN count(DISTINCT element.layer) AS count"}},"layout":{"x":9,"y":0,"width":3,"height":3},"parameterBindings":{}}],"createdAt":"2026-08-07T16:30:00.000Z","updatedAt":"2026-08-07T16:30:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_rapports_architecture_2$::jsonb, 'christophe.lacombe'),
  ('rapports-architecture', 3, $def_rapports_architecture_3${"id":"rapports-architecture","title":"Rapports d’Architecture","description":"Vue d’ensemble du modèle ArchiMate courant.","category":"Architecture","schemaVersion":2,"parameters":[],"panels":[{"id":"elements","panel":{"title":"Éléments","description":"Nombre total d’éléments ArchiMate affiché par le plugin d’exemple.","resultType":"metrics","parameters":[],"visualization":{"type":"example/progress","max":1000},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (element:Element) RETURN count(element) AS count"}},"layout":{"x":0,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"relations","panel":{"title":"Relations","description":"Nombre total de relations ArchiMate.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (:Element)-[relationship]->(:Element) RETURN count(relationship) AS count"}},"layout":{"x":3,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"vues","panel":{"title":"Vues","description":"Nombre total de vues ArchiMate.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (view:View) RETURN count(view) AS count"}},"layout":{"x":6,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"couches","panel":{"title":"Couches ArchiMate","description":"Nombre de couches présentes dans le modèle.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (element:Element) RETURN count(DISTINCT element.layer) AS count"}},"layout":{"x":9,"y":0,"width":3,"height":3},"parameterBindings":{}}],"createdAt":"2026-08-07T16:30:00.000Z","updatedAt":"2026-08-07T16:30:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_rapports_architecture_3$::jsonb, 'christophe.lacombe'),
  ('voisinage-elements', 1, $def_voisinage_elements_1${"id":"voisinage-elements","title":"Voisinage des éléments","description":"Explorez les relations directes de l’élément sélectionné.","category":"Éléments","schemaVersion":2,"parameters":[{"name":"elementId","label":"Élément","type":"string","required":true,"selector":{"source":"model-elements","elementTypes":["Stakeholder","Driver","Assessment","Goal","Outcome","Principle","Requirement","Constraint","Meaning","Value","Resource","Capability","CourseOfAction","ValueStream","BusinessActor","BusinessRole","BusinessCollaboration","BusinessInterface","BusinessProcess","BusinessFunction","BusinessInteraction","BusinessEvent","BusinessService","BusinessObject","Contract","Representation","Product","ApplicationComponent","ApplicationCollaboration","ApplicationInterface","ApplicationFunction","ApplicationInteraction","ApplicationProcess","ApplicationEvent","ApplicationService","DataObject","Node","Device","SystemSoftware","TechnologyCollaboration","TechnologyInterface","Path","CommunicationNetwork","TechnologyFunction","TechnologyProcess","TechnologyInteraction","TechnologyEvent","TechnologyService","Artifact","Equipment","Facility","DistributionNetwork","Material","WorkPackage","Deliverable","ImplementationEvent","Plateau","Gap","Location","Grouping"]}}],"panels":[{"id":"graphe-voisinage","panel":{"title":"Voisinage de l’élément","description":"Relations directes de l’élément sélectionné, dans les deux sens.","resultType":"graph","parameters":[{"name":"elementId","label":"Élément","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (root:Element {id: $elementId})\nOPTIONAL MATCH (root)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION]-(neighbor:Element)\nWITH root, collect(DISTINCT neighbor.id)[0..99] AS neighborIds\nRETURN neighborIds + root.id AS nodeIds, root.id AS emphasizedId"}},"layout":{"x":0,"y":0,"width":12,"height":8},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}},{"id":"proprietes","panel":{"title":"Propriétés","description":"Propriétés ArchiMate de l’élément sélectionné.","resultType":"table","parameters":[{"name":"elementId","label":"Élément","type":"string","required":true}],"visualization":{"type":"table"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (root:Element {id: $elementId})\nOPTIONAL MATCH (root)-[:HAS_PROPERTY]->(property:Property)\nWITH [item IN collect(property) WHERE item IS NOT NULL | {Nom: item.name, Valeur: item.value}] AS rows\nRETURN rows"}},"layout":{"x":0,"y":8,"width":12,"height":5},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}},{"id":"relations","panel":{"title":"Relations","description":"Relations entrantes et sortantes de l’élément sélectionné.","resultType":"table","parameters":[{"name":"elementId","label":"Élément","type":"string","required":true}],"visualization":{"columnOrder":["Direction","Relation","Élément","Type","Couche"],"type":"table"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (root:Element {id: $elementId})\nOPTIONAL MATCH (root)-[relationship]-(other:Element)\nWHERE relationship IS NULL OR type(relationship) <> 'HAS_PROPERTY'\nWITH root, [item IN collect(CASE WHEN relationship IS NULL THEN null ELSE {Direction: CASE WHEN startNode(relationship) = root THEN 'Sortante' ELSE 'Entrante' END, Relation: relationship.archiType, `Élément`: other.name, Type: other.type, Couche: other.layer} END) WHERE item IS NOT NULL] AS rows\nRETURN rows"}},"layout":{"x":0,"y":8,"width":12,"height":5},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}}],"tabGroups":[{"id":"details-element","tabs":[{"id":"proprietes","title":"Propriétés","panelIds":["proprietes"]},{"id":"relations","title":"Relations","panelIds":["relations"]}]}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_voisinage_elements_1$::jsonb, 'christophe.lacombe'),
  ('voisinage-elements', 2, $def_voisinage_elements_2${"id":"voisinage-elements","title":"Voisinage des éléments","description":"Explorez les relations directes de l’élément sélectionné.","category":"Éléments","schemaVersion":2,"parameters":[{"name":"elementId","label":"Élément","type":"string","required":true,"selector":{"source":"model-elements","elementTypes":["Stakeholder","Driver","Assessment","Goal","Outcome","Principle","Requirement","Constraint","Meaning","Value","Resource","Capability","CourseOfAction","ValueStream","BusinessActor","BusinessRole","BusinessCollaboration","BusinessInterface","BusinessProcess","BusinessFunction","BusinessInteraction","BusinessEvent","BusinessService","BusinessObject","Contract","Representation","Product","ApplicationComponent","ApplicationCollaboration","ApplicationInterface","ApplicationFunction","ApplicationInteraction","ApplicationProcess","ApplicationEvent","ApplicationService","DataObject","Node","Device","SystemSoftware","TechnologyCollaboration","TechnologyInterface","Path","CommunicationNetwork","TechnologyFunction","TechnologyProcess","TechnologyInteraction","TechnologyEvent","TechnologyService","Artifact","Equipment","Facility","DistributionNetwork","Material","WorkPackage","Deliverable","ImplementationEvent","Plateau","Gap","Location","Grouping"]}}],"panels":[{"id":"graphe-voisinage","panel":{"title":"Voisinage de l’élément","description":"Relations directes de l’élément sélectionné, dans les deux sens.","resultType":"graph","parameters":[{"name":"elementId","label":"Élément","type":"string","required":true}],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (root:Element {id: $elementId})\nOPTIONAL MATCH (root)-[:COMPOSITION|AGGREGATION|ASSIGNMENT|REALIZATION|SERVING|ACCESS|INFLUENCE|TRIGGERING|FLOW|SPECIALIZATION|ASSOCIATION]-(neighbor:Element)\nWITH root, collect(DISTINCT neighbor.id)[0..99] AS neighborIds\nRETURN neighborIds + root.id AS nodeIds, root.id AS emphasizedId"}},"layout":{"x":0,"y":0,"width":12,"height":8},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}},{"id":"proprietes","panel":{"title":"Propriétés","description":"Propriétés ArchiMate de l’élément sélectionné.","resultType":"table","parameters":[{"name":"elementId","label":"Élément","type":"string","required":true}],"visualization":{"type":"table"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (root:Element {id: $elementId})\nOPTIONAL MATCH (root)-[:HAS_PROPERTY]->(property:Property)\nWITH [item IN collect(property) WHERE item IS NOT NULL | {Nom: item.name, Valeur: item.value}] AS rows\nRETURN rows"}},"layout":{"x":0,"y":8,"width":12,"height":5},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}},{"id":"relations","panel":{"title":"Relations","description":"Relations entrantes et sortantes de l’élément sélectionné.","resultType":"table","parameters":[{"name":"elementId","label":"Élément","type":"string","required":true}],"visualization":{"columnOrder":["Direction","Relation","Élément","Type","Couche"],"type":"table"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (root:Element {id: $elementId})\nOPTIONAL MATCH (root)-[relationship]-(other:Element)\nWHERE relationship IS NULL OR type(relationship) <> 'HAS_PROPERTY'\nWITH root, [item IN collect(CASE WHEN relationship IS NULL THEN null ELSE {Direction: CASE WHEN startNode(relationship) = root THEN 'Sortante' ELSE 'Entrante' END, Relation: relationship.archiType, `Élément`: other.name, Type: other.type, Couche: other.layer} END) WHERE item IS NOT NULL] AS rows\nRETURN rows"}},"layout":{"x":0,"y":8,"width":12,"height":5},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}}],"tabGroups":[{"id":"details-element","tabs":[{"id":"proprietes","title":"Propriétés","panelIds":["proprietes"]},{"id":"relations","title":"Relations","panelIds":["relations"]}]}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_voisinage_elements_2$::jsonb, 'christophe.lacombe'),
  ('vue-architecture-applicative', 1, $def_vue_architecture_applicative_1${"id":"vue-architecture-applicative","title":"Vue d’ensemble applicative","description":"Synthèse des composants applicatifs, de leur documentation et des acteurs métier servis.","category":"Applications","schemaVersion":2,"parameters":[],"panels":[{"id":"composants-connectes","panel":{"title":"Composants applicatifs connectés par des flux","description":"Composants applicatifs atteints par un flux direct depuis un autre composant applicatif.","resultType":"graph","parameters":[],"visualization":{"type":"graph"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (:Element {type: 'ApplicationComponent'})-[:FLOW]->(target:Element {type: 'ApplicationComponent'})\nWHERE target.name IS NOT NULL\nWITH DISTINCT target ORDER BY target.name ASC LIMIT 100\nRETURN collect(target.id) AS nodeIds"}},"layout":{"x":0,"y":0,"width":9,"height":7},"parameterBindings":{}},{"id":"sans-documentation","panel":{"title":"Composants applicatifs sans documentation","description":"Nombre de composants applicatifs sans documentation renseignée.","resultType":"metrics","parameters":[],"visualization":{"type":"metric"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (target:Element {type: 'ApplicationComponent'})\nWHERE target.documentation IS NULL\nWITH DISTINCT target LIMIT 500\nRETURN count(target) AS count"}},"layout":{"x":9,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"acteurs-servis","panel":{"title":"Acteurs métier servis par les composants applicatifs","description":"Liste chaque composant applicatif et les acteurs métier qu'il sert directement.","resultType":"table","parameters":[{"name":"couche","label":"Couche ArchiMate","type":"enum","required":false,"defaultValue":"Business","allowedValues":["Application","Business"]}],"visualization":{"type":"table"},"query":{"datasourceId":"architecture-neo4j","language":"cypher","text":"MATCH (:Element {type: 'ApplicationComponent'})-[:SERVING]->(target:Element {type: 'BusinessActor'})\nWHERE target.name IS NOT NULL AND target.layer = $couche\nWITH DISTINCT target ORDER BY target.name ASC LIMIT 500\nRETURN collect({id: target.id, name: target.name, type: target.type}) AS rows"}},"layout":{"x":0,"y":7,"width":12,"height":5},"parameterBindings":{"couche":{"source":"constant","value":"Business"}}}],"createdAt":"2026-08-07T00:00:00.000Z","updatedAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedBy":"christophe.lacombe"}$def_vue_architecture_applicative_1$::jsonb, 'christophe.lacombe'),
